#include <stdio.h>
#include <string.h>

#define MAX_ARGS 65
#define MAX_LEN 1024

int main(int argc, char **argv) {
    int n = argc - 1;
    if (n > MAX_ARGS) { puts("TOO_MANY"); return 0; }
    if (n == 0) { puts("EMPTY"); return 0; }
    for (int i = 1; i <= n; ++i) {
        if ((int)strlen(argv[i]) > MAX_LEN) { puts("TOO_LONG"); return 0; }
    }
    const char *first = argv[1];
    size_t prefix_len = strlen(first);
    for (int i = 2; i <= n; ++i) {
        const char *s = argv[i];
        size_t len = strlen(s);
        if (len < prefix_len) prefix_len = len;
        while (prefix_len > 0 && memcmp(first, s, prefix_len) != 0) --prefix_len;
    }
    for (size_t i = 0; i < prefix_len; ++i) putchar(first[i]);
    putchar('\n');
    return 0;
}
